import functools
import inspect
from typing import ForwardRef, Any, Callable, Dict
from fastapi.dependencies.utils import get_typed_signature

class A:
    def method(self, x: "A") -> None:
        pass

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

wrapped_method = wrapper(A.method)

try:
    sig = get_typed_signature(wrapped_method)
    print("Success!")
    print(sig)
except Exception as e:
    print(f"Failed: {e}")
    import traceback
    traceback.print_exc()

